float sdLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);

    return length(pa - ba * h);
}

float S(float v) {
    vec2 r = vec2(iResolution.x, iResolution.y);
    float aa_width = 1.5/r.y;

    return smoothstep(aa_width, 0.0, v);
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec2 pos = texelFetch(iChannel0, ivec2(0, 0), 0).xy;
    vec2 b = texelFetch(iChannel0, ivec2(1, 0), 0).xy;
    vec4 r = texelFetch(iChannel0, ivec2(2, 0), 0);

    float d = sdOuter(uv);
    float d2 = sdRoundedBox(uv - pos, b, r);

    seed = (iFrame * 32);

    vec2 randPos = pos + randomInCircle()  * max(b.x, b.y);
    vec2 surfPos = randPos + sdRoundedBoxGrad(randPos, pos, b, r) * -sdRoundedBox(randPos, pos, b, r);
    vec2 closest = surfPos - sdOuterGrad(surfPos) * sdOuter(surfPos) ;


    vec3 col = vec3(0.444);

    col = mix(col, vec3(1.0), S(abs(d) - 0.001));
    col = mix(col, vec3(0.888), S(abs(d2) - 0.001));

    col = mix(col, vec3(0.125), 1.0 - S(d));
    col = mix(col, vec3(0.75), 1.0 - step(0.0, d2));  

    float lineDistance = sdLine(uv, surfPos, closest);
    col = mix(col, (col + 1.0) * 0.5, S(lineDistance));

    float surfDist = length(uv - surfPos);
    float closestDist = length(uv - closest);
    col = mix(col, (col + 1.0) * 0.5, S(surfDist - 0.01));
    col = mix(col, (col + vec3(1.0, 0.5, 0.0)) * 0.5, S(closestDist - 0.01));


    fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if(fragCoord.y < 1.0) {
        vec2 pos = texelFetch(iChannel0, ivec2(0, 0), 0).xy;
        vec2 b = texelFetch(iChannel0, ivec2(1, 0), 0).xy;
        vec4 r = texelFetch(iChannel0, ivec2(2, 0), 0);
        vec2 vb = texelFetch(iChannel0, ivec2(3, 0), 0).xy;
        vec4 vr = texelFetch(iChannel0, ivec2(4, 0), 0);
        vec2 vpos = texelFetch(iChannel0, ivec2(5, 0), 0).xy;

        if(iFrame < 1) { 
            pos = vec2(0.0, 0.0);
            b = vec2(0.04); 
            r = vec4(0.04);
            vb = vec2(0.0);
            vr = vec4(0.0);
            vpos = vec2(0.0);
        }

        seed = iFrame * 38142719;

        bool collided = false;
        vec2 sumB = vec2(0.0); 
        vec4 sumR = vec4(0.0);
        vec2 sumPos = vec2(0.0);
        float count = 0.0;
        float avgPenetration = 0.0;

        for (int i = 0; i < 64; i++) {
            vec2 randPos = pos + randomInCircle() * max(b.x, b.y);
            vec2 surfPos = randPos + sdRoundedBoxGrad(randPos, pos, b, r) * -sdRoundedBox(randPos, pos, b, r);

            float penetration = sdOuter(surfPos) + 0.015;
            float s = sign(penetration);
            if(penetration != 0.0) {
                vec4 dr;
                vec2 db, dpos;
                computeGrowthDerivatives(surfPos, pos, b, r, db);
                computePositionDerivatives(surfPos, pos, b, r, dpos);
                computeRadiusDerivatives(surfPos, pos, b, r, dr);

                sumB += db * s;
                sumR += dr * s;
                sumPos += dpos * s;

                avgPenetration += abs(penetration);
                count += 1.0;
                collided = true;
            }
        }

        if(collided) {
            avgPenetration /= count;
        }

        float damping = mix(0.95, 0.1, smoothstep(0.0, 10.0, iTime));
        float momentum = 0.99;

        if (!collided) {
            vb = vb * damping;
            vr = vr * damping;
        } else {
            float countNorm = max(1.0, count);

            float updateScale = smoothstep(-0.015, 0.0, avgPenetration)  * 0.1;
            vb = vb * momentum + (sumB / countNorm) * 0.01 * updateScale;
            vr = vr * momentum + -(sumR / countNorm) * 0.01 * updateScale;
            vpos = vpos * momentum + (sumPos / countNorm) * 0.01 * updateScale;

            vb *= damping;
            vr *= damping;
            vpos *= damping;
        }

        b += vb;
        r -= vr;
        pos += vpos;
        ;

        pos = clamp(pos, vec2(-0.3), vec2(0.3));

        vb = mix(vb, vec2(0.0), step(b, vec2(0.02)));
        vr = mix(vr, vec4(0.0), step(r, vec4(0.01)));
        vr = mix(vr, vec4(0.0), step(vec4(min(b.x, b.y)), r));
        vpos = mix(vpos, vec2(0.0), step(abs(pos), vec2(0.3)));

        if(fragCoord.x < 1.0) fragColor = vec4(pos, 0.0, 1.0);
        else if(fragCoord.x < 2.0) fragColor = vec4(b, 0.0, 1.0);
        else if(fragCoord.x < 3.0) fragColor = r;
        else if(fragCoord.x < 4.0) fragColor = vec4(vb, 0.0, 1.0);
        else if(fragCoord.x < 5.0) fragColor = vr;
        else if(fragCoord.x < 6.0) fragColor = vec4(vpos, 0.0, 1.0);
        else fragColor = texelFetch(iChannel0, ivec2(fragCoord), 0);
    }
    else fragColor = texelFetch(iChannel0, ivec2(fragCoord), 0);
}

const float DELTA = 0.001;


int seed = 539458;
int randInt() { seed = seed*0x343fd + 0x269ec3; return (seed>>16)&32767; }
float frand() { return float(randInt())/32767.0; }

void srand( ivec2 p, int frame ) {
    int n = frame;
    n = (n<<13)^n; n = n*(n*n*15731+789221)+1376312589; 
    n += p.y;
    n = (n<<13)^n; n = n*(n*n*15731+789221)+1376312589;
    n += p.x;
    n = (n<<13)^n; n = n*(n*n*15731+789221)+1376312589;
    seed = n;
}


vec2 randomInCircle( void ) {
    float an = 6.283185*frand();
    return vec2(cos(an),sin(an));
}

float sdRoundedBox(vec2 p, vec2 b, vec4 r) {
    r.xy = (p.x > 0.0) ? r.xy : r.zw;
    r.x = (p.y > 0.0) ? r.x : r.y;
    vec2 q = abs(p) - b + r.x;
    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r.x;
}

float sdRoundedBox(vec2 pos, vec2 center, vec2 b, vec4 r) {
    vec2 p = pos - center;
    r.xy = (p.x > 0.0) ? r.xy : r.zw;
    r.x = (p.y > 0.0) ? r.x : r.y;
    vec2 q = abs(p) - b + r.x;
    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r.x;
}

float sdBox( in vec2 p, in vec2 b ) {
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}


float sdHexagram( in vec2 p, in float r ) {
    const vec4 k = vec4(-0.5,0.8660254038,0.5773502692,1.7320508076);
    p = abs(p);
    p -= 2.0*min(dot(k.xy,p),0.0)*k.xy;
    p -= 2.0*min(dot(k.yx,p),0.0)*k.yx;
    p -= vec2(clamp(p.x,r*k.z,r*k.w),r);
    return length(p)*sign(p.y);
}

float sdOuter(vec2 p) {
    return sdRoundedBox(p + vec2(0.0, 0.0), vec2(0.08, 0.35), vec4(0.04, 0.04, 0.04, 0.04)); ;
}

vec2 sdRoundedBoxGrad(vec2 p, vec2 c, vec2 b, vec4 r) {
    return vec2(
        sdRoundedBox(p + vec2(DELTA, 0.0), c, b, r) - sdRoundedBox(p - vec2(DELTA, 0.0), c, b, r),
        sdRoundedBox(p + vec2(0.0, DELTA), c, b, r) - sdRoundedBox(p - vec2(0.0, DELTA), c, b, r)
    ) / (2.0 * DELTA);
}


vec2 sdOuterGrad(vec2 p) {
    return vec2(
        sdOuter(p + vec2(DELTA, 0.0)) - sdOuter(p - vec2(DELTA, 0.0)),
        sdOuter(p + vec2(0.0, DELTA)) - sdOuter(p - vec2(0.0, DELTA))
    ) / (2.0 * DELTA);
}

