    // How box size affects surface distance
void computeGrowthDerivatives(vec2 surfPos, vec2 pos, vec2 b, vec4 r, out vec2 db) {
    db = vec2(
        sdRoundedBox(surfPos - pos, b + vec2(DELTA, 0.0), r) - 
        sdRoundedBox(surfPos - pos, b - vec2(DELTA, 0.0), r),
        sdRoundedBox(surfPos - pos, b + vec2(0.0, DELTA), r) - 
        sdRoundedBox(surfPos - pos, b - vec2(0.0, DELTA), r)
    ) / (2.0 * DELTA);
}

// How position affects surface distance
void computePositionDerivatives(vec2 surfPos, vec2 pos, vec2 b, vec4 r, out vec2 dpos) {
    dpos = vec2(
        sdRoundedBox(surfPos - (pos + vec2(DELTA, 0.0)), b, r) - 
        sdRoundedBox(surfPos - (pos - vec2(DELTA, 0.0)), b, r),
        sdRoundedBox(surfPos - (pos + vec2(0.0, DELTA)), b, r) - 
        sdRoundedBox(surfPos - (pos - vec2(0.0, DELTA)), b, r)
    ) / (2.0 * DELTA);
}

// How radii affect surface distance
void computeRadiusDerivatives(vec2 surfPos, vec2 pos, vec2 b, vec4 r, out vec4 dr) {
    dr = vec4(
        sdRoundedBox(surfPos - pos, b, r + vec4(DELTA,0,0,0)) - 
        sdRoundedBox(surfPos - pos, b, r - vec4(DELTA,0,0,0)),
        sdRoundedBox(surfPos - pos, b, r + vec4(0,DELTA,0,0)) - 
        sdRoundedBox(surfPos - pos, b, r - vec4(0,DELTA,0,0)),
        sdRoundedBox(surfPos - pos, b, r + vec4(0,0,DELTA,0)) - 
        sdRoundedBox(surfPos - pos, b, r - vec4(0,0,DELTA,0)),
        sdRoundedBox(surfPos - pos, b, r + vec4(0,0,0,DELTA)) - 
        sdRoundedBox(surfPos - pos, b, r - vec4(0,0,0,DELTA))
    ) / (2.0 * DELTA);
}
